Summary:
[{
    "SDK_name": "Vungle SDK",
    "API_name": "setCCPAStatus",
    "conditions": [
      "As of July 1, 2020, California Consumer Privacy Act (CCPA) will be enforced and publishers must update to Android SDK 6.7.0 to comply with CCPA."
    ],
    "effects": [
      "The setCCPAStatus method takes the user's consent status to specify whether user has OPTED_IN or OPTED_OUT for the California Consumer Privacy Act (CCPA).",
      "In accordance with CCPA, the consent status is opted in by default unless setCCPAStatus has been explicitly called to set it as opted out.",
      "getCCPAStatus method may return null if not set but will be treated as opted-in."
    ],
    "parameter_configuations": [
      {
        "parameter_values": [
            "true",
            "false"
        ],
        "conditions": [
            "For setting opted-in status to true, User consent is considered to be there by default unless setCCPAStatus has been explicitly called to set it as opted out.",
            "For setting opted-out status to false, setCCPAStatus has to be explicitly called by the app developers."
        ],
        "effects": [
            "When opted-in status is set to true, user's consent is considered given for data processing under CCPA regulations.",
            "When opted-out status is set to false, user's consent is considered to be withdrawn and data processing should not happen under CCPA regulations."
        ]
      }
    ]
  }]
